package com.vandorlabs.neoforge.gear.track.client;

import com.vandorlabs.gear.track.core.*;
import com.vandorlabs.neoforge.gear.*;
import com.vandorlabs.neoforge.gear.track.*;
import java.util.*;
import net.minecraft.client.Minecraft;
import net.minecraft.client.renderer.RenderType;
import net.minecraft.client.renderer.block.model.BakedQuad;
import net.minecraft.client.resources.model.*;
import net.minecraft.core.Direction;
import net.minecraft.resources.ResourceLocation;
import net.minecraft.util.RandomSource;
import net.neoforged.neoforge.client.model.data.ModelData;

/** Passive actual emitted record oracle, independent of the terrain wrapper's vertex transform. */
@net.neoforged.fml.common.EventBusSubscriber(modid="vandorlabs",value=net.neoforged.api.distmarker.Dist.CLIENT)
public final class NativeTrackRenderChecks {
    private static boolean done;
    private static int checks;
    private static void need(boolean ok,String why){checks++;if(!ok)throw new AssertionError("Native Track emitted: "+why);}
    private static List<BakedQuad> all(BakedModel model){var quads=new ArrayList<BakedQuad>();var random=RandomSource.create(0);quads.addAll(model.getQuads(null,null,random));for(var face:Direction.values())quads.addAll(model.getQuads(null,face,random));return quads;}
    @net.neoforged.bus.api.SubscribeEvent public static void tick(net.neoforged.neoforge.client.event.ClientTickEvent.Post event){if(done||!Boolean.getBoolean("vandorlabs.trackRenderChecks"))return;var mc=Minecraft.getInstance();if(mc.level==null||mc.player==null||mc.getOverlay()!=null)return;done=true;try{run(mc);System.out.println("[vandorlabs][track-render] PASS checks="+checks);}catch(Throwable failed){failed.printStackTrace();System.out.println("[vandorlabs][track-render] FAIL "+failed);throw new IllegalStateException("Track emitted records",failed);}}
    private static void run(Minecraft mc){need(System.getProperty("vandorlabs.trackRuntime")==null&&System.getProperty("vandorlabs.legacyLanding")==null,"ordinary public defaults without enable flags");var catalog=net.minecraft.core.registries.BuiltInRegistries.CREATIVE_MODE_TAB.get(net.minecraft.resources.ResourceLocation.parse("vandorlabs:vandorlabs"));net.minecraft.world.item.CreativeModeTabs.tryRebuildTabContents(mc.level.enabledFeatures(),false,mc.level.registryAccess());for(var item:NativeGearBindings.ITEMS.entrySet())if(item.getValue().getBlock() instanceof NativeTrackBlock track){long count=catalog.getDisplayItems().stream().filter(stack->stack.is(item.getValue())).count(),search=catalog.getSearchTabDisplayItems().stream().filter(stack->stack.is(item.getValue())).count();need(count==(track.defaultStyle()==0?1:0)&&search==count,"canonical Track catalog hides legacy aliases");}for(var item:com.vandorlabs.neoforge.landing.NativeLandingBindings.ITEMS.values()){need(catalog.getDisplayItems().stream().filter(stack->stack.is(item)).count()==1&&catalog.getSearchTabDisplayItems().stream().filter(stack->stack.is(item)).count()==1,"three canonical standalone side wheels");need(item.getBlock().getExplosionResistance()==6,"released side-wheel explosion resistance getter");}need(NativeGearBindings.BLOCKS.get("compact_track").getExplosionResistance()==4.8F,"released Track explosion resistance getter");com.vandorlabs.neoforge.seating.NativeSeatPlayerChecks.verifyPublicCatalog(mc);var block=NativeGearBindings.BLOCKS.get("compact_track");need(block instanceof NativeTrackBlock,"canonical Track registered");int cases=0;
        for(int style=0;style<3;style++)for(var facing:Direction.Plane.HORIZONTAL)for(int belt:new int[]{0,1,5,15})for(int mount:new int[]{0,1,3}){
            int key=TrackVisualState.validatedKey(belt,mount,0,0,0);var state=block.defaultBlockState().setValue(NativeGearBlock.FACING,facing);var model=mc.getBlockRenderer().getBlockModel(state);var data=ModelData.builder().with(NativeTrackEntity.VISUAL,new NativeTrackEntity.Visual(style,facing.get2DDataValue(),key,true)).build();var emitted=model.getQuads(state,null,RandomSource.create(0),data,RenderType.cutoutMipped());var expected=new ArrayList<BakedQuad>();var turns=new ArrayList<Integer>();
            TrackMeshPolicy.emit(TrackTopology.Style.values()[style],Math.floorMod(facing.get2DDataValue()+2,4),key,part->{var authored=mc.getModelManager().getModel(ModelResourceLocation.standalone(ResourceLocation.parse("vandorlabs:block/track/"+part.name)));for(var quad:all(authored)){expected.add(quad);turns.add(part.quarterTurns);}});
            need(expected.size()==emitted.size(),"quad count style="+style+" facing="+facing+" key="+key);for(int q=0;q<expected.size();q++){var source=expected.get(q);var actual=emitted.get(q);need(source.getSprite().contents().name().equals(actual.getSprite().contents().name())&&!actual.getSprite().contents().name().getPath().contains("missingno"),"authored sprite identity");int[] before=source.getVertices(),after=actual.getVertices();int stride=before.length/4;need(after.length==before.length&&stride>=8,"complete record format");int turn=turns.get(q);for(int v=0;v<4;v++){int i=v*stride;double x=Float.intBitsToFloat(before[i]),z=Float.intBitsToFloat(before[i+2]);for(int n=0;n<turn;n++){double old=x;x=1-z;z=old;}need(Math.abs(Float.intBitsToFloat(after[i])-x)<1e-6&&Math.abs(Float.intBitsToFloat(after[i+2])-z)<1e-6&&before[i+1]==after[i+1],"Source clockwise authored position");for(int field=3;field<stride;field++)if(field!=7)need(before[i+field]==after[i+field],"UV/color/light/extended record parity");int normal=before[i+7],nx=(byte)normal,ny=(byte)(normal>>>8),nz=(byte)(normal>>>16);for(int n=0;n<turn;n++){int old=nx;nx=-nz;nz=old;}int out=after[i+7];need((byte)out==nx&&(byte)(out>>>8)==ny&&(byte)(out>>>16)==nz,"rotated authored normal");}}
            var hidden=ModelData.builder().with(NativeTrackEntity.VISUAL,new NativeTrackEntity.Visual(style,facing.get2DDataValue(),key,false)).build();need(model.getQuads(state,null,RandomSource.create(0),hidden,RenderType.cutoutMipped()).isEmpty(),"moving members suppress terrain duplicate");cases++;
        }need(cases==144,"all styles/cardinal facings/masks/mounts");for(var entry:com.vandorlabs.neoforge.landing.NativeLandingBindings.ITEMS.entrySet())padding(mc,new net.minecraft.world.item.ItemStack(entry.getValue()));}
    private static void padding(Minecraft mc,net.minecraft.world.item.ItemStack stack){var model=mc.getItemRenderer().getModel(stack,mc.level,mc.player,0);var gui=model.getTransforms().gui;int vertices=0;for(var quad:all(model)){need(!quad.getSprite().contents().name().getPath().contains("missingno"),"side wheel authored texture");int[] raw=quad.getVertices();for(int i=0;i<4;i++){int at=i*(raw.length/4);double x=(Float.intBitsToFloat(raw[at])-.5)*gui.scale.x(),y=(Float.intBitsToFloat(raw[at+1])-.5)*gui.scale.y(),z=(Float.intBitsToFloat(raw[at+2])-.5)*gui.scale.z(),rz=Math.toRadians(gui.rotation.z()),ry=Math.toRadians(gui.rotation.y()),rx=Math.toRadians(gui.rotation.x()),a=x*Math.cos(rz)-y*Math.sin(rz);y=x*Math.sin(rz)+y*Math.cos(rz);x=a;a=x*Math.cos(ry)+z*Math.sin(ry);z=z*Math.cos(ry)-x*Math.sin(ry);x=a;y=y*Math.cos(rx)-z*Math.sin(rx);x+=gui.translation.x();y+=gui.translation.y();need(Math.abs(x)<.47&&Math.abs(y)<.47,"side wheel item padding "+stack);vertices++;}}need(vertices>=24,"visible side wheel authored item vertices");}
    private NativeTrackRenderChecks(){}
}
